from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod
import copy
import math

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        grid: List[List[int]] = message.message[0].data[1]
        prev_move = message.message[0].data[0]  # [(r, c), value] or None
        N = len(grid)
        box_size = int(math.isqrt(N))

        def valid_numbers(g, r, c):
            if g[r][c] != 0:
                return []
            used = set()
            # row & col
            for i in range(N):
                used.add(g[r][i])
                used.add(g[i][c])
            # box
            br = (r // box_size) * box_size
            bc = (c // box_size) * box_size
            for i in range(br, br + box_size):
                for j in range(bc, bc + box_size):
                    used.add(g[i][j])
            return [v for v in range(1, N+1) if v not in used]

        def allowed_positions(prev, g):
            empties = []
            if prev is None:
                for i in range(N):
                    for j in range(N):
                        if g[i][j] == 0:
                            empties.append((i, j))
                return empties
            (pr, pc), _ = prev
            for (i, j) in [ (pr, j) for j in range(N) ] + [ (i, pc) for i in range(N) ]:
                if 0 <= i < N and 0 <= j < N and g[i][j] == 0:
                    empties.append((i, j))
            if empties:
                return empties
            # no empties in row/col => anywhere
            for i in range(N):
                for j in range(N):
                    if g[i][j] == 0:
                        empties.append((i, j))
            return empties

        # Find all our candidate moves
        own_positions = allowed_positions(prev_move, grid)
        # Try to find a winning move
        for (r, c) in own_positions:
            for val in valid_numbers(grid, r, c):
                newg = copy.deepcopy(grid)
                newg[r][c] = val
                # Compute opponent's allowed positions
                opp_positions = allowed_positions(((r, c), val), newg)
                # Check if opponent has any legal number anywhere
                opp_has_move = False
                for (orow, ocol) in opp_positions:
                    if valid_numbers(newg, orow, ocol):
                        opp_has_move = True
                        break
                if not opp_has_move:
                    # Found forced win
                    move = [(r, c), val]
                    return Info(
                        sender=self.__class__.__name__,
                        receiver=message.sender,
                        difficulty=message.difficulty,
                        message=[BaseMessageDataType(data=move, type='custom')]
                    )
        # No immediate win found: play first valid move
        for (r, c) in own_positions:
            vals = valid_numbers(grid, r, c)
            if vals:
                move = [(r, c), vals[0]]
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=move, type='custom')]
                )
        # If we have no move (should not happen in a valid mid-game), pass None
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=None, type='custom')]
        )

