import copy

class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        grid: List[List[int]] = message.message[0].data[1]
        prev_move = message.message[0].data[0]  # [(r,c),v] or None
        N = len(grid)
        sub = int(N ** 0.5)

        def get_domain(move, board):
            # return list of empty (r,c) positions where next player must play
            if move is None:
                return [(i, j) for i in range(N) for j in range(N) if board[i][j] == 0]
            (pr, pc), _ = move
            row_cells = [(pr, j) for j in range(N) if board[pr][j] == 0]
            col_cells = [(i, pc) for i in range(N) if board[i][pc] == 0]
            dom = list(dict.fromkeys(row_cells + col_cells))  # unique
            if dom:
                return dom
            # if none, may play anywhere
            return [(i, j) for i in range(N) for j in range(N) if board[i][j] == 0]

        def possible_values(board, r, c):
            used = set(board[r])
            used |= {board[i][c] for i in range(N)}
            br, bc = (r // sub) * sub, (c // sub) * sub
            for i in range(br, br + sub):
                for j in range(bc, bc + sub):
                    used.add(board[i][j])
            return [v for v in range(1, N + 1) if v not in used]

        # 1) gather our allowed moves
        our_domain = get_domain(prev_move, grid)
        best_move = None
        best_score = float('inf')

        # try each candidate for immediate win or heuristic
        for (r, c) in our_domain:
            vals = possible_values(grid, r, c)
            if not vals:
                continue
            for v in vals:
                # simulate
                new_board = copy.deepcopy(grid)
                new_board[r][c] = v
                # opponent domain and options
                opp_dom = get_domain(((r, c), v), new_board)
                total_opts = 0
                has_legal = False
                for (orow, ocol) in opp_dom:
                    opts = possible_values(new_board, orow, ocol)
                    if opts:
                        has_legal = True
                        total_opts += len(opts)
                # if no legal opponent move, we win immediately
                if not has_legal:
                    move = [(r, c), v]
                    return Info(
                        sender=self.__class__.__name__,
                        receiver=message.sender,
                        difficulty=message.difficulty,
                        message=[BaseMessageDataType(data=move, type='custom')]
                    )
                # otherwise keep track for heuristic minimization
                if total_opts < best_score:
                    best_score = total_opts
                    best_move = (r, c, v)

        # no immediate win—return the move that most restricts opponent
        if best_move:
            r, c, v = best_move
            move = [(r, c), v]
        else:
            # fallback: fill the first empty with any legal value
            for i in range(N):
                for j in range(N):
                    if grid[i][j] == 0:
                        vals = possible_values(grid, i, j)
                        if vals:
                            move = [(i, j), vals[0]]
                            break
                else:
                    continue
                break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=move, type='custom')]
        )

