                return empties
            (pr, pc), _ = prev
            row_positions = [(pr, c) for c in range(N) if grid[pr][c] == 0]
            col_positions = [(r, pc) for r in range(N) if grid[r][pc] == 0]
            allowed = row_positions + [pos for pos in col_positions if pos not in row_positions]
            return allowed if allowed else empties

        def possible_values(g, r, c):
            used = set(g[r])
            used |= {g[i][c] for i in range(N)}
            br, bc = (r // block) * block, (c // block) * block
            for i in range(br, br + block):
                for j in range(bc, bc + block): used.add(g[i][j])
            return [v for v in range(1, N+1) if v not in used]

