            for v in candidates:
                sim = copy.deepcopy(grid)
                sim[r][c] = v
                if not opponent_has_move(sim, (r, c)):
                    move = [(r, c), v]
                    break
            if move:
                break
        if move is None:
            # fallback to first legal
            for (r, c) in allowed:
                vals = possible_values(grid, r, c)
                if vals:
                    move = [(r, c), vals[0]]
                    break

        return Info(
            sender=self.__class__.__name__,
