from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod
import math

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        grid = message.message[0].data[1]  # 2D list
        prev_move = message.message[0].data[0]  # [(r,c),v] or None
        N = len(grid)
        block = int(math.isqrt(N))
        # helper to compute candidates for a cell
        def candidates(r, c):
            used = set()
            # row and column
            for i in range(N):
                if grid[r][i] != 0: used.add(grid[r][i])
                if grid[i][c] != 0: used.add(grid[i][c])
            # block
            br = (r // block) * block
            bc = (c // block) * block
            for i in range(br, br + block):
                for j in range(bc, bc + block):
                    if grid[i][j] != 0:
                        used.add(grid[i][j])
            return [v for v in range(1, N+1) if v not in used]
        # find empty cells
        empty = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == 0]
        # restrict to same row or col as prev_move if possible
        if prev_move is not None:
            (pr, pc), _ = prev_move
            allowed = [(i, j) for (i, j) in empty if i == pr or j == pc]
        else:
            allowed = empty[:]
        # if no allowed empties, allow anywhere
        if not allowed:
            allowed = empty[:]
        # compute candidates and pick tightest
        best = None
