            if not opts:
                continue
            if best_opts is None or len(opts) < len(best_opts):
                best_opts = opts
                best = (r, c)
                if len(opts) == 1:
                    break
        if best is None:
            # fallback: any empty
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        vlist = valid_numbers_at(i, j, grid)
                        if vlist:
                            best = (i, j)
                            best_opts = vlist
                            break
                if best:
                    break
        val = min(best_opts) if best_opts else 1
        move = [best, val]
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=move, type='custom')]
        )"
}
